// PREVIEW PROTOTYPE (react/logos): team logos and player headshots.
// The URLs come from src/data/images.json, generated by
// scripts/export_web_images.R from basketball_test.schedule (logos) and the
// cached basket.co.il team pages (photos). Israeli league only; EuroLeague has
// no image source. If this goes ahead the URLs move to season_teams and
// player_display_names_v and arrive with the names instead.
import { createContext, useContext } from "react";
import images from "@/data/images.json";

type BySeason = Record<string, Record<string, string>>;
const LOGOS = images.logos as BySeason;
const PHOTOS = images.photos as BySeason;

export type ImageScope = { league: string; season: string } | null;
export const ImageScopeContext = createContext<ImageScope>(null);
export const useImageScope = () => useContext(ImageScopeContext);

const id = (v: unknown) => {
  const n = Number(v);
  return v == null || v === "" || !Number.isFinite(n) ? null : String(n);
};

/** The team's logo in that season, else in the latest season that has one
 * (a team keeps its logo across seasons far more often than not). */
export function teamLogo(scope: ImageScope, team: unknown): string | null {
  const t = id(team);
  if (!scope || scope.league !== "il" || t == null) return null;
  const exact = LOGOS[scope.season]?.[t];
  if (exact) return exact;
  const seasons = Object.keys(LOGOS).sort().reverse();
  for (const s of seasons) if (LOGOS[s][t]) return LOGOS[s][t];
  return null;
}

/** The player's headshot for that season and team (no cross-season guess:
 * provider player ids are recycled between seasons). */
export function playerPhoto(
  scope: ImageScope,
  team: unknown,
  player: unknown,
): string | null {
  const t = id(team),
    p = id(player);
  if (!scope || scope.league !== "il" || t == null || p == null) return null;
  return PHOTOS[scope.season]?.[`${t}:${p}`] ?? null;
}
